import { NextResponse } from 'next/server';
import { getOrCreatePlayer } from '@/lib/device';
import { supabaseWrite } from '@/lib/supabase';
import { createHash } from 'node:crypto';
import { parseDeviceKey } from '@/lib/device';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/**
 * POST /api/device, the client's only way to get a device key. It sends whatever it already
 * has in localStorage (or nothing, on a first visit); this always answers with a valid signed
 * key, minting a fresh player row when the one sent in was missing, malformed or unknown.
 *
 * An optional `slateId` also returns whether this player already called on that slate, so the
 * page can render the locked-in state on load instead of a second round trip.
 */
export async function POST(req: Request) {
  let body: { deviceKey?: string; slateId?: string } = {};
  try { body = await req.json(); } catch { /* a first visit sends no body at all */ }

  if (!parseDeviceKey(body.deviceKey)) {
    const db = supabaseWrite();
    const address = req.headers.get('cf-connecting-ip')
      ?? req.headers.get('x-real-ip')
      ?? req.headers.get('x-forwarded-for')?.split(',').at(-1)?.trim()
      ?? 'unknown';
    const key = createHash('sha256').update(`wirecall-device:${address}`).digest('hex');
    const { data, error } = await db.rpc('compound_rate_limit_hit', {
      p_key: key, p_limit: 5, p_window_sec: 3600,
    });
    const row = (Array.isArray(data) ? data[0] : data) as { allowed?: boolean; retry_after?: number } | null;
    if (error || !row?.allowed) {
      return NextResponse.json(
        { error: 'too many new devices' },
        { status: 429, headers: { 'Retry-After': String(row?.retry_after ?? 60) } },
      );
    }
  }
  const { player, deviceKey } = await getOrCreatePlayer(body.deviceKey ?? null);

  let call: { storyId: string; direction: string | null; won: boolean | null; pointsAwarded: number | null } | null = null;
  if (body.slateId) {
    const db = supabaseWrite();
    const { data } = await db.from('wc_calls')
      .select('story_id,direction,won,points_awarded')
      .eq('slate_id', body.slateId).eq('player_id', player.id).maybeSingle();
    if (data) call = {
      storyId: data.story_id as string, direction: data.direction as string | null,
      won: data.won as boolean | null, pointsAwarded: data.points_awarded as number | null,
    };
  }

  return NextResponse.json({
    deviceKey,
    call,
    player: {
      displayName: player.displayName,
      points: player.points,
      streakCurrent: player.streakCurrent,
      streakBest: player.streakBest,
      seasonPass: player.seasonPass,
      hasEmail: Boolean(player.email),
    },
  });
}

