import { NextResponse } from 'next/server';
import Stripe from 'stripe';
import { supabaseWrite } from '@/lib/supabase';
import { getOrCreatePlayer } from '@/lib/device';
import { siteOrigin } from '@/lib/origin';
/* THE ONE EDIT AGAINST THE LIVE FILE, and scripts/check-register.mjs byte-proves that it is
 * the only one. The live route imports WIRE_PASS from '@/lib/prices'; in this app the price is
 * authored once, in src/lib/product.ts, which carries prices.ts's own label, cents and
 * description with the source named beside them. A second file holding 4.99 is a second place
 * for it to drift. */
import { WIRE_PASS } from '@/lib/product';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

function stripeClient(): Stripe {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY is not set, checkout cannot run without it.');
  return new Stripe(key);
}

const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

/**
 * The checkout page's own mark, so a buyer sees WireCall rather than the account's default
 * ("Compound", the shared display name on acct_1U94AeHX6skw2rM7). Rasterised from
 * src/app/icon.svg and uploaded 2026-09-04 (scripts/stripe-branding.mjs pattern, same as
 * OutRip); logo and icon are two uploads of the same pixels because Stripe refuses a
 * business_logo file in the icon slot.
 */
const BRANDING = {
  display_name: 'WireCall',
  border_style: 'rounded',
  logo: { type: 'file', file: 'file_1UC2GvHX6skw2rM7MIElRAUq' },
  icon: { type: 'file', file: 'file_1UC2GwHX6skw2rM7NVKGfrFd' },
  // The account's own colours are OutRip's (background #f8f9fb, button #c2277f). WireCall's
  // accent is a single solid amber, not a gradient, so unlike OutRip's checkout it can safely
  // pin the button colour per session without picking an arbitrary stop out of a gradient.
  button_color: '#f4b344',
} as const;

/**
 * POST /api/checkout { email, deviceKey }. The Wire Pass ties to an email because history and
 * a named leaderboard entry both need to survive a cleared browser; the device key still
 * names which player's row gets marked paid once Stripe confirms.
 */
export async function POST(req: Request) {
  let body: { email?: string; displayName?: string; deviceKey?: string };
  try { body = await req.json(); } catch { return NextResponse.json({ error: 'bad request' }, { status: 400 }); }

  const email = String(body.email ?? '').trim().toLowerCase();
  const displayName = String(body.displayName ?? '').trim();
  if (!EMAIL_RE.test(email)) {
    return NextResponse.json({ error: 'That does not look like an email address.' }, { status: 400 });
  }
  if (!/^[\p{L}\p{N}][\p{L}\p{N} ._'’-]{1,23}$/u.test(displayName)) {
    return NextResponse.json({ error: 'Choose a board name between 2 and 24 characters.' }, { status: 400 });
  }

  const { player, deviceKey } = await getOrCreatePlayer(body.deviceKey ?? null);
  if (player.seasonPass) {
    return NextResponse.json({ error: 'This device already has a Wire Pass.', deviceKey }, { status: 409 });
  }

  const origin = siteOrigin(req);
  const db = supabaseWrite();
  await db.from('wc_players').update({ display_name: displayName }).eq('id', player.id);

  /* Declared outside the try so the catch can clean it up. The row is written BEFORE Stripe is
   * called, because the session needs its id, so a Stripe failure used to leave a pending order
   * carrying the buyer's address behind forever: no failed status, no expiry, nothing that ever
   * looked at it again. Measured 2026-09-19 with Stripe unreachable: three attempts left three
   * pending orders and three players, every one holding the address. */
  let orderId: string | null = null;

  try {
    const { data: order, error: orderErr } = await db.from('wc_orders').insert({
      player_id: player.id, email, amount_cents: WIRE_PASS.cents, status: 'pending',
    }).select('id').single();
    if (orderErr) throw new Error(orderErr.message);
    orderId = order.id as string;

    const session = await stripeClient().checkout.sessions.create({
      mode: 'payment',
      branding_settings: BRANDING,
      managed_payments: { enabled: false },
      client_reference_id: order.id as string,
      customer_email: email,
      metadata: { order_id: order.id as string, player_id: player.id, product: 'wirecall' },
      payment_intent_data: {
        statement_descriptor_suffix: 'WIRECALL',
        description: `WireCall, ${WIRE_PASS.label} for ${email}`,
        metadata: { order_id: order.id as string, product: 'wirecall' },
      },
      line_items: [{
        quantity: 1,
        price_data: {
          currency: 'usd',
          unit_amount: WIRE_PASS.cents,
          product_data: {
            name: `WireCall, ${WIRE_PASS.label}`,
            description: WIRE_PASS.description,
          },
        },
      }],
      success_url: `${origin}/pass?order=${order.id}`,
      cancel_url: `${origin}/pass?cancelled=1`,
    });
    if (!session.url) throw new Error('Stripe returned a session with no url.');

    await db.from('wc_orders').update({ stripe_session_id: session.id }).eq('id', order.id);
    return NextResponse.json({ url: session.url, deviceKey });
  } catch (e) {
    console.error('[checkout]', e);
    /* Nothing was charged, so nothing should be kept. The address was collected to put on a
     * receipt for a payment that never started. */
    if (orderId) {
      const { error } = await db.from('wc_orders').delete().eq('id', orderId).eq('status', 'pending');
      if (error) console.error('[checkout] could not clear the abandoned order', error.message);
    }
    return NextResponse.json({ error: 'Checkout could not start. Nothing was charged.', deviceKey }, { status: 500 });
  }
}

